class RunTests {
  public void runTests() {
    Object[][] tests = {
        // Example 1
        {
            new String[][] {
                { "alice", "192.168.1.1" },
                { "alice", "192.168.1.2" },
                { "bob", "192.168.1.2" },
                { "bob", "192.168.1.1" }
            },
            true
        },
        // Example 2
        {
            new String[][] {
                { "alice", "192.168.1.1" },
                { "bob", "192.168.1.2" }
            },
            false
        },
        // Additional test cases
        {
            new String[][] {
                { "alice", "1.1.1.1" },
                { "alice", "2.2.2.2" },
                { "bob", "2.2.2.2" },
                { "bob", "1.1.1.1" },
                { "charlie", "3.3.3.3" }
            },
            true
        },
        {
            new String[][] {},
            false
        }
    };

    MultiAccountCheating solution = new MultiAccountCheating();
    for (Object[] test : tests) {
      String[][] usersArray = (String[][]) test[0];
      List<List<String>> users = Arrays.stream(usersArray)
          .map(Arrays::asList)
          .collect(Collectors.toList());
      boolean want = (boolean) test[1];
      boolean got = solution.solve(users);
      if (got != want) {
        throw new RuntimeException(String.format(
            "\nsolve(%s): got: %b, want: %b\n",
            users, got, want));
      }
    }
  }
}

public class Solution {
  public static void main(String[] args) {
    new RunTests().runTests();
  }
}
